"""Build the destination map and booking guide; reuses the established site design."""
from pathlib import Path
import json, re, sys
sys.path.insert(0, str(Path(__file__).resolve().parent))
import build_tours as site
R = site.ROOT
areas = [
 ('serengeti','Serengeti',34.83,-2.33,'Wide plains & wildlife','Allow several days for the Serengeti and the drives that connect it to the northern circuit. Migration locations change with conditions; ask about your travel dates.','images/optimized/serengeti.webp','safari.html','serengeti'),
 ('ngorongoro','Ngorongoro',35.50,-3.236,'A crater chapter','Combine a crater visit with a northern safari. Confirm entry arrangements, accommodation and the full driving itinerary in your quote.','images/optimized/ngorongoro.webp','safari.html','ngorongoro'),
 ('manyara','Lake Manyara',35.82,-3.637,'Lake country & forest','A compact northern park to discuss alongside Tarangire or Ngorongoro. Conditions and wildlife sightings vary throughout the year.','images/optimized/manyara.webp','safari.html','manyara'),
 ('tarangire','Tarangire',36.0,-3.83,'Baobabs & elephant country','Choose a focused day safari or make Tarangire the opening chapter of a longer northern circuit. Your pickup point affects time on the road.','images/optimized/tarangire.webp','tarangire-day-safari.html','tarangire'),
 ('arusha','Arusha',36.683,-3.386,'A northern safari starting point','Discuss arrival transfers and a night before your safari. Airport, pickup location and accommodation should be agreed before you travel.','images/stories/zebras-safari-vehicle.webp','packages.html?category=safari','safari'),
 ('moshi','Moshi & Marangu',37.34,-3.34,'Coffee, waterfalls & foothills','Meet the everyday side of Tanzania. Add a coffee visit, village walk or waterfall experience around Moshi and Marangu to your mountain journey.','images/stories/coffee-roasting.webp','local-tanzania.html','local'),
 ('kilimanjaro','Kilimanjaro',37.355,-3.067,'From forest to Uhuru','Compare the 6-day Marangu, 7-day Machame and 8-day Lemosho examples. Add arrival and departure days; choose your route with time to acclimatize.','images/stories/uhuru-summit-david.webp','kilimanjaro.html','kilimanjaro'),
 ('zanzibar','Zanzibar',39.32,-6.13,'Stone Town & turquoise water','Pair a guided Stone Town walk with coast time or a boat excursion. Mainland-to-island flights, transfers and marine fees need a separate place in your quote.','images/stories/zanzibar-blue-water.webp','zanzibar.html','zanzibar')]

def point(lon, lat): return ((lon-29)*54+24, (-lat-0.8)*54+24)
outline=json.loads((R/'data/tanzania-outline.geojson').read_text())
path=' '.join('M'+' L'.join(f'{point(lon,lat)[0]:.1f},{point(lon,lat)[1]:.1f}' for lon,lat in ring)+' Z' for ring in outline['geometry']['coordinates'])
pins=''.join(f'<a href="{a[7]}" data-map-select="{a[0]}" aria-label="Explore {site.esc(a[1])}"><circle cx="{point(a[2],a[3])[0]:.1f}" cy="{point(a[2],a[3])[1]:.1f}" r="7" data-map-dot="{a[0]}"/><text x="{point(a[2],a[3])[0]+10:.1f}" y="{point(a[2],a[3])[1]+4:.1f}">{i+1}</text></a>' for i,a in enumerate(areas))
svg=f'<svg viewBox="0 0 650 650" role="img" aria-label="Tanzania planning map with eight destinations; use the numbered buttons below"><path d="{path}"/><g>{pins}</g><text x="475" y="425" class="ocean-label">INDIAN OCEAN</text></svg>'
buttons=''.join(f'<button type="button" data-destination="{a[0]}" aria-pressed="{str(i==0).lower()}"><span>{i+1:02}</span> {site.esc(a[1])}</button>' for i,a in enumerate(areas))
first=areas[0]
mapblock=f'''<div class="discovery-grid" data-discovery><div class="destination-map">{svg}<p class="map-note">Approximate destination locations, not driving routes or administrative boundaries. Mainland outline: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth ↗</a>. Zanzibar is marked offshore.</p></div><div><div class="destination-buttons" aria-label="Choose a destination">{buttons}</div><article class="destination-detail" aria-live="polite" aria-atomic="true">{site.img(first[6],'Wildlife landscape in the Serengeti')}<div><p class="eyebrow" data-area-tag>{first[4]}</p><h3 data-area-name>{first[1]}</h3><p data-area-description>{first[5]}</p><div class="destination-actions"><a class="btn btn-primary" data-area-tours href="{first[7]}">Explore journeys ↗</a><a data-area-plan href="index.html?trip={first[8]}#contact">Plan this chapter</a><a data-area-map href="https://www.google.com/maps/search/?api=1&amp;query={first[3]},{first[2]}" target="_blank" rel="noopener noreferrer">See location on Google Maps ↗</a></div></div></article></div></div>'''
home=R/'index.html'; text=home.read_text()
section='<section class="section" id="discover-tanzania"><div class="section-heading split-heading"><div><p class="eyebrow">CONNECT YOUR CHAPTERS</p><h2>Find your place<br>in Tanzania.</h2></div><p>Choose a destination on the map, discover its rhythm and build a journey around the places that matter to you. <a href="explore-tanzania.html">Explore the full guide ↗</a></p></div>'+mapblock+'</section>'
if 'id="discover-tanzania"' in text: text=re.sub(r'<section class="section" id="discover-tanzania">.*?</section>',lambda _:section,text,flags=re.S)
else: text=text.replace('<section id="experiences"',section+'\n<section id="experiences"')
home.write_text(text)
data=[dict(id=a[0],name=a[1],longitude=a[2],latitude=a[3],tag=a[4],description=a[5],image=a[6],tours=a[7],trip=a[8],width=site.image_size(a[6])[0],height=site.image_size(a[6])[1]) for a in areas]
(R/'destination-data.js').write_text('/* Generated by scripts/build_discovery.py. */\n(function(r,d){if(typeof module==="object"&&module.exports)module.exports=d;else r.DavidDestinations=d;})(globalThis,'+json.dumps(data,ensure_ascii=False)+');\n')

def page(name,title,description,body):
    head=re.search(r'<head>.*?</head>',home.read_text(),re.S)[0]
    head=re.sub(r'<title>.*?</title>',f'<title>{site.esc(title)} | David Explora</title>',head)
    head=re.sub(r'<meta name="description"[^>]+>',f'<meta name="description" content="{site.esc(description)}">',head)
    head=re.sub(r'<meta property="og:(?:title|description|url)"[^>]+>','',head)
    head=re.sub(r'<link rel="canonical"[^>]+>',f'<link rel="canonical" href="{site.ORIGIN}/{name}">',head)
    (R/name).write_text('<!DOCTYPE html><html lang="en">'+head+'<body><a class="skip-link" href="#main">Skip to content</a>'+site.HEADER+'<main id="main"><section class="section"><p class="eyebrow">PERSONAL JOURNEYS · TANZANIA</p><h1>'+title+'</h1><p class="discovery-intro">'+description+'</p>'+body+'</section></main>'+site.FOOTER+site.FLOAT+'<script src="journey.js" defer></script><script src="script.js" defer></script></body></html>')
page('explore-tanzania.html','Eight places. Your own story.','Explore the northern parks, Kilimanjaro foothills and Zanzibar. Use the destinations below to start a conversation about a realistic route.',mapblock+'<div class="booking-callout"><h2>Make the journey fit your time.</h2><p>A park day, a summit trek and an island stay each need their own travel time. David can help connect them, confirm transfers and explain the costs before you commit.</p><a class="btn btn-primary" href="index.html#contact">Build my Tanzania trip ↗</a></div>')
page('how-to-book.html','A conversation. A clear quote. Your journey.','Plan directly with David, review the arrangements and confirm your trip in writing. Your inquiry is the first step.', '''<div class="booking-steps"><article><p class="eyebrow">01 / START WITH YOUR IDEA</p><h2>Tell David what matters.</h2><p>Choose a journey or share your dates, group size, budget and interests. Prepare your request on WhatsApp or email, then press Send in that app.</p><a href="index.html#contact">Prepare my request ↗</a></article><article><p class="eyebrow">02 / KNOW WHAT YOU ARE BOOKING</p><h2>Review your written quote.</h2><p>Confirm the itinerary, accommodation, transport, activities, inclusions, exclusions and total price. Ask which fees and transfers are included and how changes or cancellations are handled.</p></article><article><p class="eyebrow">03 / AGREE THE PAYMENT</p><h2>Pay against a confirmed quote.</h2><p>Ask David for the available payment method, currency, deposit amount, balance deadline and any processing charges in writing. Online checkout is not currently available on this website. A trip request does not collect money or reserve a place.</p></article><article><p class="eyebrow">04 / KEEP YOUR CONFIRMATION</p><h2>Get the details before departure.</h2><p>Keep your payment receipt and written booking confirmation. Confirm pickup, contact details, packing guidance and any outstanding balance before traveling.</p></article></div><div class="booking-callout"><h2>Questions worth asking.</h2><details><summary>Is the guide price my final price?</summary><p>No. Guide prices are estimates with group-size assumptions shown on each itinerary. Dates, availability, accommodation and transfers affect your personal quote.</p></details><details><summary>Can I combine a safari with Kilimanjaro or Zanzibar?</summary><p>Yes, ask for a combined itinerary. Include preparation, recovery and transfers rather than counting only activity days.</p></details><details><summary>How do I know my request arrived?</summary><p>The website prepares a draft. Send it in WhatsApp or your email app and wait for David’s reply. Copy the message if your email app does not open.</p></details><p><a href="terms.html">Read the booking information</a> · <a href="privacy.html">Privacy information</a></p></div><section data-business-presence hidden><h2>Discover David Explora elsewhere.</h2><p>Visit our public listings to read traveler feedback and see the experiences available on each platform.</p><div data-business-links class="destination-actions"></div></section>''')
for p in R.glob('*.html'):
    t=p.read_text()
    if 'discovery.css' not in t: t=t.replace('</head>','<link rel="stylesheet" href="discovery.css"></head>')
    if 'discovery.js' not in t: t=t.replace('</body>','<script src="destination-data.js" defer></script><script src="business-links.js" defer></script><script src="discovery.js" defer></script></body>')
    t=t.replace('<a href="travel-guide.html">Travel guide</a>','<a href="explore-tanzania.html">Explore Tanzania</a>')
    if 'Tanzania planning guide</a><a href="explore-tanzania.html"' not in t:
        t=t.replace('<a href="travel-guide.html">Tanzania planning guide</a>','<a href="travel-guide.html">Tanzania planning guide</a><a href="explore-tanzania.html">Destination map</a><a href="how-to-book.html">How to book</a>')
    p.write_text(t)
site.sitemap()
print('Built destination discovery and booking guide; linked all pages.')
